            final Subscriber<? super R> a = downstream;

            int missing = 1;

            for (;;) {

                if (cancelled) {
                    return;
                }

                if (done) {
                    if (delayErrors) {
                        if (active.get() == null) {
                            errors.tryTerminateConsumer(a);
                            return;
                        }
                    } else {
