                        if (inner.done) {
                            if (!delayErrors) {
                                Throwable err = errors.get();
                                if (err != null) {
                                    disposeInner();
                                    errors.tryTerminateConsumer(a);
                                    return;
                                } else
                                if (q.isEmpty()) {
