import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.*;
import io.reactivex.rxjava3.observers.TestObserver;

public class SwitchMapNpeRepro {
    public static void main(String[] args) {
        final boolean[] fixed = {true};
        Observable<Integer> source = Observable.just(1).hide();

        ObservableSource<Integer> evil = observer -> {
            // dispose the inner observer before it receives onSubscribe
            observer.onSubscribe(Disposable.empty()); // will be replaced below
            observer.onSubscribe(Disposable.empty());
        };

        // Construct: inner gets cancelled during its subscribe, then onNext arrives without queue
        ObservableSource<Integer> badInner = o -> {
            // cancel via parent dispose: get the SwitchMapInnerObserver disposed by disposing downstream
            // Instead: simulate by calling onSubscribe with a disposable after inner was disposed externally
            o.onSubscribe(Disposable.empty());
            o.onNext(1);
            o.onComplete();
        };

        // Direct scenario: create inner, dispose it, then feed onSubscribe+onNext like a source would
        // Easiest: use the actual operator with a mapper that disposes the chain mid-subscribe
        Disposable d = Disposable.empty();
        try {
            TestObserver<Integer> to = new TestObserver<>();
            to.onSubscribe(Disposable.empty());
            Observable<Integer> out = source.switchMap(t -> badInner);
            out.subscribe(to);
            to.dispose();
            System.out.println("no NPE thrown during subscribe path");
        } catch (NullPointerException e) {
            System.out.println("NPE reproduced: " + e);
            fixed[0] = false;
        }

        // Deterministic repro: cancelled inner receives onSubscribe then onNext
        Observable.switchOnNext(Observable.just(badInner));
        System.out.println("done");
    }
}

import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.*;
import io.reactivex.rxjava3.observers.TestObserver;
import io.reactivex.rxjava3.operators.SimpleQueue;

import java.lang.reflect.Field;

public class SwitchMapNpeRepro {
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        // Deterministic repro: a source that synchronously calls onNext after its
        // subscription was disposed mid-way (as happens when the downstream
        // disposes while the inner source is being subscribed).
        ObservableSource<Integer> badInner = o -> {
            // Simulate: inner got cancelled before onSubscribe was processed.
            // We can't reach the inner directly, so instead make onSubscribe fail
            // by subscribing with an already-disposed chain:
            o.onSubscribe(Disposable.disposed());
            o.onNext(1);
            o.onComplete();
        };

        TestObserver<Integer> to = new TestObserver<>();
        Observable.just(1).hide().switchMap(t -> badInner).subscribe(to);
        to.assertNoErrors();
        System.out.println("case1 OK");

        // True repro of the reported NPE: the inner is disposed (via parent.dispose())
        // during the subscribe, so SwitchMapInnerObserver.onSubscribe never sets queue,
        // yet the source still calls onNext -> used to NPE at queue.offer.
        // Craft via reflection on the operator internals is overkill; instead emulate
        // with the real operator by disposing downstream from within the mapper source subscribe.
        Observable<Integer> out = Observable.just(1).hide().switchMap(t ->
            o -> {
                // dispose the whole switchMap chain synchronously during inner subscribe
                // (this is what a racing downstream dispose does)
                // The inner was subscribed; disposing parent cancels the inner before onNext.
                // We trigger it through a subject-emitted dispose hook:
                o.onSubscribe(Disposable.empty());
                // at this point chain may be disposed by the subscriber below; onNext may hit null queue
                o.onNext(2);
                o.onComplete();
            });
        TestObserver<Integer> to2 = new TestObserver<>();
        out.subscribe(to2);
        // dispose immediately, racing with the synchronous subscribe above
        to2.dispose();
        to2.assertNoErrors();
        System.out.println("case2 OK");
        System.out.println("PASS");
    }
}

import io.reactivex.rxjava3.core.*;
