        ObservableSource<Integer> badInner = o -> {
            // dispose the whole switchMap chain synchronously during the inner
            // subscribe: disposeInner() cancels the inner observer
            upstream.get().dispose();
            // DisposableHelper.setOnce now fails -> queue never gets assigned
            o.onSubscribe(Disposable.empty());
            // pre-fix: NPE at SwitchMapInnerObserver.onNext(queue.offer)
            o.onNext(1);
            o.onComplete();
        };

        Observable.just(1).hide().switchMap(t -> badInner).subscribe(downstream);

        if (received.get() != 0) {
            System.out.println("FAIL: item emitted after dispose");
        } else {
            System.out.println("PASS");
        }
    }
}

